332	/// A referenced alias whose expansion is `unevaluated` — it holds a conditional or mapped type the resolver can't
333	/// evaluate, or an alias named for that reason — shows as its name with its arguments as written
334	/// (`StyleProp<MantineSpacing>`), the way TypeScript prints it, rather than as that type's source text. An object
335	/// expansion stays: its fields still read, and only the unevaluated field shows source.
336	/// A generic alias with `args` bound, its omitted parameters at their defaults. An alias that is a conditional over a bare
337	/// type parameter (`type Exclude<T, U> = T extends U ? never : T`) distributes over the members of the argument bound to
338	/// it, each evaluated alone and the results united, as TypeScript does.
339	#[allow(clippy::too_many_arguments)]
340	fn expand_alias(
341	    alias: &CollectedTypeAlias,
342	    params: &[CompactString],
343	    defaults: Option<&[Option<CollectedType>]>,
344	    args: &[CollectedType],
345	    args_file: &Utf8Path,
346	    declared_file: &Utf8Path,
347	    ctx: &ResolutionContext,
348	    state: &mut ResolveState,
349	    depth: u8,
350	) -> PropType {
351	    let args = &*super::substitute::mark_args(ctx, state, args_file, args);
352	    let subst =
353	        super::substitute::bind_declared(params, defaults, args, args_file, declared_file, &mut state.diagnostics);
354	    if let Some(param) = super::evaluate::distributive_param(alias)
355	        && let Some(bound) = subst.get(param)
356	    {
357	        let members = literal_members(super::evaluate::union_members(bound, args_file, ctx, 0), ctx, state, depth);
358	        if members.len() != 1 {
359	            let caller = state.enter_scope(TypeScope::default());
360	            let results: Vec<PropType> = members
361	                .into_iter()
362	                .map(|(member, member_file)| {
363	                    let mut one = subst.clone();
364	                    let member = CollectedType::AtFile { file: member_file, inner: Box::new(member) };
365	                    one.insert(param, member);
366	                    resolve_type_alias_type(&super::substitute::substitute_alias(alias, &one), ctx, state, depth)
367	                })
368	                .collect();
369	            state.leave_scope(caller);
370	            return super::primitives::union_of(results);
371	        }
372	    }
373	    let caller = state.enter_scope(TypeScope::default());
374	    let expanded = resolve_type_alias_type(&super::substitute::substitute_alias(alias, &subst), ctx, state, depth);
375	    state.leave_scope(caller);
376	    expanded
377	}
