379	/// `members` with each one that is not already a literal or primitive resolved (`(typeof SIZES)[number]`, a template
380	/// literal), replaced by the literals it comes to; one that comes to something else stays as written.
381	fn literal_members(
382	    members: Vec<super::evaluate::Located>,
383	    ctx: &ResolutionContext,
384	    state: &mut ResolveState,
385	    depth: u8,
386	) -> Vec<super::evaluate::Located> {
387	    let mut out = Vec::with_capacity(members.len());
388	    for (member, file) in members {
389	        let plain = matches!(
390	            member,
391	            CollectedType::StringLiteral(_)
392	                | CollectedType::NumberLiteral(_)
393	                | CollectedType::BoolLiteral(_)
394	                | CollectedType::String
395	                | CollectedType::Number
396	                | CollectedType::Boolean
397	                | CollectedType::Null
398	                | CollectedType::Undefined
399	        );
400	        if plain {
401	            out.push((member, file));
402	            continue;
403	        }
404	        let resolved = resolve_collected_type(&member, &file, ctx, state, depth + 1);
405	        match literals_of(&resolved) {
406	            Some(literals) => out.extend(literals.into_iter().map(|literal| (literal, file.clone()))),
407	            None => out.push((member, file)),
408	        }
409	    }
410	    out
411	}
