413	/// The literals and primitives `ty` is a union of, as collected types; `None` when any member is something else.
414	fn literals_of(ty: &PropType) -> Option<Vec<CollectedType>> {
415	    Some(match ty {
416	        PropType::StringLiteral(s) => vec![CollectedType::StringLiteral(s.as_str().into())],
417	        PropType::NumberLiteral(n) => vec![CollectedType::NumberLiteral(*n)],
418	        PropType::BoolLiteral(b) => vec![CollectedType::BoolLiteral(*b)],
419	        PropType::LiteralUnion { members, .. } => {
420	            members.iter().map(|m| CollectedType::StringLiteral(m.as_str().into())).collect()
421	        }
422	        PropType::Null => vec![CollectedType::Null],
423	        PropType::Undefined => vec![CollectedType::Undefined],
424	        PropType::String => vec![CollectedType::String],
425	        PropType::Number => vec![CollectedType::Number],
426	        PropType::Boolean => vec![CollectedType::Boolean],
427	        PropType::Never => vec![],
428	        PropType::Union(members) => {
429	            let mut all = Vec::new();
430	            for member in members {
431	                all.extend(literals_of(member)?);
432	            }
433	            all
434	        }
435	        _ => return None,
436	    })
437	}
