439	/// `name` as TypeScript's lib declares it, when that is a conditional or an intersection and every part of it evaluates
440	/// with `args` (`Exclude`, `Extract`, `NonNullable`). A lib alias that needs inference (`ReturnType`) or a mapped type
441	/// (`Partial`) leaves its result unevaluated, and the caller keeps its shortcut.
442	fn evaluate_lib_alias(
443	    name: &str,
444	    args: &[CollectedType],
445	    consuming_file: &Utf8Path,
446	    ctx: &ResolutionContext,
447	    state: &mut ResolveState,
448	    depth: u8,
449	) -> Option<PropType> {
450	    let (lib_file, alias) = ctx.named_types.lookup_ambient_alias(&ctx.ambient_global_files, name)?;
451	    let can_evaluate = matches!(
452	        alias,
453	        CollectedTypeAlias::Intersection { .. }
454	            | CollectedTypeAlias::Passthrough { target: CollectedType::Conditional { .. }, .. }
455	    );
456	    let params = ctx.named_types.lookup_type_alias_params(lib_file, name).filter(|_| can_evaluate)?;
457	    let defaults = ctx.named_types.lookup_type_param_defaults(lib_file, name);
458	    // Its diagnostics are the lib's, not the project's: kept only when the whole alias evaluates.
459	    let mut branch = state.detached();
460	    let expanded = expand_alias(alias, params, defaults, args, consuming_file, lib_file, ctx, &mut branch, depth);
461	    if branch.named_unevaluated || expanded.holds_unevaluated_type() {
462	        return None;
463	    }
464	    state.absorb_detached(branch);
465	    Some(expanded)
466	}
