468	/// `NonNullable<A | B | undefined>` as `A | B` (csstype's `Property.Border<TLength>`) when none of the members that stay
469	/// can hold `null` or `undefined` itself. `None` leaves the call as written.
470	fn without_nullish(
471	    name: &str,
472	    args: &[CollectedType],
473	    file: &Utf8Path,
474	    ctx: &ResolutionContext,
475	) -> Option<CollectedType> {
476	    if name != "NonNullable" || args.len() != 1 || !super::may_be_ts_lib_type(name, file, ctx) {
477	        return None;
478	    }
479	    let mut kept = Vec::new();
480	    let members = match &args[0] {
481	        CollectedType::Union(members) => members.as_slice(),
482	        single => std::slice::from_ref(single),
483	    };
484	    for member in members {
485	        match member {
486	            CollectedType::Null | CollectedType::Undefined => {}
487	            other if can_hold_nullish(other, file, ctx, 0) => return None,
488	            other => kept.push(other.clone()),
489	        }
490	    }
491	    Some(match kept.len() {
