#!/bin/sh
# run.sh <bin> <tag> [lane...]: extract the six projects with --no-checker (struct) and the checker (checker).
# Checker runs are watched: killed above 14 GB RSS.
B=$1; T=$2; shift 2; LANES=${*:-struct checker}
F=/Users/gabe/Projects/caliper-fixtures; C=$F/corpora
cd /Users/gabe/Projects/caliper-fixtures/shrink/parity || exit 1
src() {
  case $1 in
    chakra-only) echo $F/checker-default/chakra-only/src ;;
    gate-large) echo $F/gate-large/src ;;
    shadcn) echo $C/shadcn-ui/apps/v4 ;;
    spectrum) echo $C/react-spectrum/packages ;;
    mantine) echo $C/mantine/packages/@mantine/core/src ;;
    antd) echo $C/ant-design/components ;;
  esac
}
for p in ${PROJECTS:-chakra-only gate-large shadcn spectrum mantine antd}; do
  for lane in $LANES; do
    flag=""; [ $lane = struct ] && flag=--no-checker
    $B extract --json --quiet --no-cache $flag --src $(src $p) > $T-$p.$lane.json 2> $T-$p.$lane.err &
    pid=$!; peak=0
    while kill -0 $pid 2>/dev/null; do
      rss=$(ps -o rss= -p $pid 2>/dev/null | tr -d ' '); rss=${rss:-0}
      [ "$rss" -gt $peak ] && peak=$rss
      if [ "$rss" -gt 14680064 ]; then kill -9 $pid; echo "KILLED $p $lane at $rss KB"; fi
      sleep 0.5
    done
    wait $pid; echo "$T $p $lane exit=$? peakMB=$((peak/1024))"
  done
done

