                    })
                    .collect::<Option<_>>()?,
            )
        }
        other => Some(
            literal_set(other)?
                .into_iter()
                .map(|name| Key { name, required: true, description: String::new(), tags: Default::default() })
                .collect(),
        ),
    }
}

